package main

import (
	"fmt"
)

var d = map[string]int{
	"C":  0,
	"C#": 1,
	"D":  2,
	"D#": 3,
	"E":  4,
	"F":  5,
	"F#": 6,
	"G":  7,
	"G#": 8,
	"A":  9,
	"B":  10,
	"H":  11,
}

func chrd(x, y, z string) string {
	a := (d[y] - d[x] + 12) % 12
	b := (d[z] - d[y] + 12) % 12
	if a == 4 && b == 3 {
		return "major"
	}
	if a == 3 && b == 4 {
		return "minor"
	}
	return "0"
}

func main() {
	var x, y, z string
	fmt.Scan(&x, &y, &z)

	if res := chrd(x, y, z); res != "0" {
		fmt.Println(res)
	} else if res := chrd(x, z, y); res != "0" {
		fmt.Println(res)
	} else if res := chrd(y, x, z); res != "0" {
		fmt.Println(res)
	} else if res := chrd(y, z, x); res != "0" {
		fmt.Println(res)
	} else if res := chrd(z, x, y); res != "0" {
		fmt.Println(res)
	} else if res := chrd(z, y, x); res != "0" {
		fmt.Println(res)
	} else {
		fmt.Println("strange")
	}
}

