		"F#": 6, "G": 7, "G#": 8, "A": 9, "B": 10, "H": 11,
	}

	perms := [][3]string{
		{x, y, z}, {x, z, y}, {y, x, z},
		{y, z, x}, {z, x, y}, {z, y, x},
